UPDATE sys90_after_service
   SET sys90_worker = #{r.worker}
     , sys90_due_date = #{r.dueDate}
     , sys90_state_cd = #{r.stateCd}
     , sys90_happen_remedy = #{r.happenRemedy}
     , sys90_remarks = #{r.remarks}
 WHERE sys90_after_service_id = #{r.afterServiceId}

UPDATE sys90_after_service
   SET sys90_remarks = #{remarks}
 WHERE sys90_after_service_id = #{afterServiceId}

mapper.select:
SELECT 
  FROM sys90_after_service a
       INNER JOIN sys01_company b ON a.sys90_company_id = b.sys01_company_id
 WHERE a.sys90_company_id = #{p.companyId}


   AND COALESCE(a.sys90_state_cd, ' ') LIKE #{p.stateCode}


   AND COALESCE(a.sys90_state_cd, ' ') NOT IN ('10', '90')


   AND COALESCE(a.sys90_type_yn, ' ') LIKE #{p.typeYn}
   AND CONCAT(a.sys90_happen_reason, a.sys90_reg_emp_nm) LIKE #{p.searchText}
   AND COALESCE(a.sys90_confirm_yn, 'false') LIKE #{p.confirmYn}
   AND f_trunc(a.sys90_happen_date) BETWEEN #{p.happenStartDate} AND #{p.happenEndDate}
 ORDER BY a.sys90_happen_date DESC

mapper.insert:
WITH upsert AS
(
    UPDATE sys90_after_service
       SET sys90_company_id = #{companyId}
         , sys90_reg_emp_nm = #{r.regEmpNm}
         , sys90_type_yn = #{r.typeYn}
         , sys90_happen_date = #{r.happenDate}
         , sys90_happen_reason = #{r.happenReason}
         , sys90_confirm_yn = #{r.confirmYn}
     WHERE sys90_after_service_id = #{r.afterServiceId}
    RETURNING *
)
INSERT INTO sys90_after_service
       (sys90_after_service_id, sys90_company_id, sys90_reg_emp_nm, sys90_type_yn, sys90_happen_date, sys90_happen_reason, sys90_confirm_yn)
SELECT #{r.afterServiceId}, #{companyId}, #{r.regEmpNm}, #{r.typeYn}, #{r.happenDate}, #{r.happenReason}, #{r.confirmYn}
 WHERE NOT EXISTS (SELECT * FROM upsert)
